export function t(key: keyof typeof zh, params: Record<string, string | number> = {}) {
  const strings = /^zh\b/i.test(document.documentElement.lang) ? zh : en
  return strings[key].replace(/\{(\w+)\}/g, (token, name: string) => String(params[name] ?? token))
}
